import{_ as a}from"./chunks/strategy-static-settings.DNh4yEZS.js";import{_ as e,o,c as i,a2 as r}from"./chunks/framework.BqDA2HS7.js";const c="/RefractRouter/strategy-static.svg",_=JSON.parse('{"title":"Static · 静态","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/static.md","filePath":"strategies/static.md"}'),s={name:"strategies/static.md"};function d(n,t,l,h,p,m){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="static-·-静态" tabindex="-1">Static · 静态 <a class="header-anchor" href="#static-·-静态" aria-label="Permalink to &quot;Static · 静态&quot;">​</a></h1><p>Static 在新任务开始时选一个执行模型，工具续接沿用选择。它不调用 Task Judge 或审核器。</p><figure class="doc-diagram"><img src="'+c+'" alt="Static 在任务开始固定或按权重抽样一次，任务内保持"><figcaption>Static 是最简单的策略：选一次、用到底，零 Judge 零审核。</figcaption></figure><h2 id="当前设置的真实含义" tabindex="-1">当前设置的真实含义 <a class="header-anchor" href="#当前设置的真实含义" aria-label="Permalink to &quot;当前设置的真实含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>当前实现</th></tr></thead><tbody><tr><td>Fixed</td><td>固定使用共用设置中的“高效执行模型”及其推理等级</td></tr><tr><td>Random</td><td>按高效／强执行两个角色的冻结权重，每任务随机选择一次</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">当前 Random 的范围</p><p>当前版本不是任意数量模型的独立 Static 池。Task／Composite 有多模型池，Static 随机仍是 两个角色的加权对照。这里如实记录实现边界，不把计划中的产品形式描述为已完成。</p></div><p>“固定高效角色”是程序默认值，不表示用户曾主动配置，也不表示 Router 已经判断这个 模型对任务最合适。你选择哪个模型承担该角色，Static 就使用哪个。</p><h2 id="哪些配置必要" tabindex="-1">哪些配置必要 <a class="header-anchor" href="#哪些配置必要" aria-label="Permalink to &quot;哪些配置必要&quot;">​</a></h2><p>Fixed 只需要高效执行角色、真实推理参数、价格、能力、数据域和预算。 不需要强执行、任务判别和 Advisor 审核角色。</p><p>Random 需要两个执行角色及权重。权重 <code>1:1</code> 表示同等抽样概率；<code>3:1</code> 表示 75% 与 25%。 随机种子便于复现对照，不是模型质量或费用参数。续接不会重新抽样。</p><h2 id="典型用途" tabindex="-1">典型用途 <a class="header-anchor" href="#典型用途" aria-label="Permalink to &quot;典型用途&quot;">​</a></h2><p>先验证真实模型和原生工具，再作为其他策略的固定基线。随机模式适合实验， 不能保证每次选择质量达标或更省钱。</p><h2 id="系统设置示范" tabindex="-1">系统设置示范 <a class="header-anchor" href="#系统设置示范" aria-label="Permalink to &quot;系统设置示范&quot;">​</a></h2><p>打开 <strong>设置 → 插件 → RefractAgent 规划路由 → 正在编辑的策略：Static</strong>。</p><figure class="doc-screenshot compact"><a href="/screenshots/dsh-20261014/strategy-static-settings.png" target="_blank" rel="noopener"><img src="'+a+'" alt="实际 Static 设置：固定或随机模式、随机种子 4、两角色权重各 1"></a><figcaption>2026-10-14 实际界面：模式下拉框决定固定或随机；种子与权重只参与随机路径。</figcaption></figure><p>截图里的种子 <code>4</code> 和权重 <code>1:1</code> 是配置示例。先在共用模型资料中配置两个角色，再选择 随机模式；角色模型与推理等级一并冻结。若只希望验证一个模型，选择 Fixed 即可。 按权重抽取的是每个新任务的执行器；同一任务读文件、运行测试、总结时沿用它， 不会每轮重新抛一次硬币。</p><h2 id="轨迹应该看到什么" tabindex="-1">轨迹应该看到什么 <a class="header-anchor" href="#轨迹应该看到什么" aria-label="Permalink to &quot;轨迹应该看到什么&quot;">​</a></h2><p>固定／随机理由、选中的真实模型与推理等级、调用用途、费用和耗时。 如果 Fixed 产生额外 Judge 调用，需核对是否实际选择了其他策略。</p><h3 id="真实案例" tabindex="-1">真实案例 <a class="header-anchor" href="#真实案例" aria-label="Permalink to &quot;真实案例&quot;">​</a></h3><p>2026-09-29 验收批次的 static-01 任务（<code>reports/dsh-strategy-stability-20260929-v3/records.jsonl</code>）： 用户要求“只回复 <code>STATIC_01_OK</code>，不要调用工具，也不要添加其他文字”。 冻结随机种子选中 <code>deepseek-v4.1-flash</code>，1 次受管调用，费用 3.116 AFP，首字 1.79 秒， 总延迟 1.80 秒，决策原因 <code>static-random-selected</code>。同一批次 12 项 Static 任务里， 随机策略同时覆盖了 <code>deepseek-v4-flash</code>（如 static-02：0.622 AFP）与 V4.1 两条执行路线。</p><p>业务场景可用“读取已有说明并改写成三条要点”作为固定基线：先记录固定模型的质量、 总费用和等待，再与其他策略比较。随机模式的用途是产生对照，抽到便宜模型不等于任务已验收。 本页截图是当前配置示范；案例调用使用<a href="./../planning.html#六策略真实运行案例">历史冻结配置</a>。</p>',21)])])}const g=e(s,[["render",d]]);export{_ as __pageData,g as default};
